import { CellCanvas } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function gridEqual(actual: string[][], expected: string[][], message: string): void {
  equal(JSON.stringify(actual), JSON.stringify(expected), message);
}

function expectError(
  constructor: typeof TypeError | typeof RangeError,
  action: () => unknown,
  message: string,
): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof constructor, `${message}: wrong exception type`);
    return;
  }
  throw new Error(`${message}: expected an exception`);
}

for (const width of [0, -1, 1.5, Number.MAX_SAFE_INTEGER + 1, Number.NaN]) {
  expectError(RangeError, () => new CellCanvas(width, 1), `invalid width ${String(width)}`);
}
for (const height of [0, -1, 1.5, Number.MAX_SAFE_INTEGER + 1, Number.NaN]) {
  expectError(RangeError, () => new CellCanvas(1, height), `invalid height ${String(height)}`);
}
expectError(TypeError, () => new CellCanvas(1, 1, 3 as unknown as string), 'non-string empty values are rejected');

const canvas = new CellCanvas(5, 2, '.');
gridEqual(canvas.snapshot(), [['.', '.', '.', '.', '.'], ['.', '.', '.', '.', '.']], 'constructor initializes the grid');
const values = ['A', 'B'];
canvas.fillColumns(values);
gridEqual(canvas.snapshot(), [['A', 'A', 'A', 'B', 'B'], ['A', 'A', 'A', 'B', 'B']], 'column selection uses floor');
equal(values.join(','), 'A,B', 'fill input is not mutated');

const narrow = new CellCanvas(2, 1, '-');
narrow.fillColumns(['a', 'b', 'c', 'd']);
gridEqual(narrow.snapshot(), [['a', 'c']], 'more values than columns still uses the floor formula');

const beforeInvalidFill = canvas.snapshot();
expectError(TypeError, () => canvas.fillColumns([]), 'empty fill arrays are rejected');
const sparse = new Array<string>(2);
sparse[0] = 'valid';
expectError(TypeError, () => canvas.fillColumns(sparse), 'sparse arrays are rejected');
expectError(TypeError, () => canvas.fillColumns(['valid', 1 as unknown as string]), 'all fill entries are validated');
gridEqual(canvas.snapshot(), beforeInvalidFill, 'invalid fill operations are atomic');

const initialAnchor = canvas.getAnchor();
equal(initialAnchor.horizontal, 'left', 'initial horizontal anchor is left');
equal(initialAnchor.vertical, 'top', 'initial vertical anchor is top');
canvas.setAnchor('right', 'bottom');
const anchorA = canvas.getAnchor();
const anchorB = canvas.getAnchor();
equal(anchorA.horizontal, 'right', 'horizontal anchor is updated');
equal(anchorA.vertical, 'bottom', 'vertical anchor is updated');
assert(anchorA !== anchorB, 'getAnchor returns a fresh object');
expectError(TypeError, () => canvas.setAnchor('LEFT' as never, 'top'), 'invalid horizontal anchors are rejected');
expectError(TypeError, () => canvas.setAnchor('left', 'center' as never), 'invalid vertical anchors are rejected');
equal(canvas.getAnchor().horizontal, 'right', 'invalid anchor changes do not change horizontal state');
equal(canvas.getAnchor().vertical, 'bottom', 'invalid anchor changes do not change vertical state');

canvas.clearArea(1, 0, 2, 1);
gridEqual(canvas.snapshot(), [['A', '.', '.', 'B', 'B'], ['A', 'A', 'A', 'B', 'B']], 'clearArea uses a half-open rectangle');
canvas.clearArea(undefined, 1, undefined, 1);
gridEqual(canvas.snapshot(), [['A', '.', '.', 'B', 'B'], ['.', '.', '.', '.', '.']], 'omitted coordinates and width use defaults');
const zeroBefore = canvas.snapshot();
canvas.clearArea(5, 2, 0, 0);
gridEqual(canvas.snapshot(), zeroBefore, 'zero-sized boundary rectangles are no-ops');

for (const args of [
  [-1, 0, 1, 1],
  [0, 0, -1, 1],
  [0.5, 0, 1, 1],
  [4, 0, 2, 1],
  [0, 2, 1, 1],
  [Number.MAX_SAFE_INTEGER, 0, 1, 1],
] as const) {
  const stable = canvas.snapshot();
  expectError(RangeError, () => canvas.clearArea(args[0], args[1], args[2], args[3]), `invalid rectangle ${args.join(',')}`);
  gridEqual(canvas.snapshot(), stable, 'invalid rectangles do not change the grid');
}

const snapshot = canvas.snapshot();
snapshot[0][0] = 'mutated';
gridEqual(canvas.snapshot(), [['A', '.', '.', 'B', 'B'], ['.', '.', '.', '.', '.']], 'snapshot deeply copies rows');
canvas.clearArea();
gridEqual(canvas.snapshot(), [['.', '.', '.', '.', '.'], ['.', '.', '.', '.', '.']], 'no-argument clear resets the whole grid');

