#[path = "solution.rs"]
mod solution;

use solution::{FixedGrid, GridError, HeldInput};

fn assert_bounded_exact_time_carry() {
    let mut grid = FixedGrid::new(1, 1, u64::MAX).unwrap();
    let input = HeldInput::default();

    assert_eq!(grid.advance(u64::MAX - 1, &input), 0);
    assert_eq!((grid.x, grid.y), (0, 0));
    assert_eq!(grid.advance(u64::MAX, &input), 1);
    assert_eq!((grid.x, grid.y), (0, 0));
    assert_eq!(grid.advance(1, &input), 1);
    assert_eq!((grid.x, grid.y), (0, 0));
    assert_eq!(grid.advance(0, &input), 0);
}

#[test]
fn constructor_validates_in_required_order() {
    assert_eq!(FixedGrid::new(0, 0, 0), Err(GridError::ZeroStep));
    assert_eq!(FixedGrid::new(0, 0, 1), Err(GridError::ZeroWidth));
    assert_eq!(FixedGrid::new(1, 0, 1), Err(GridError::ZeroHeight));
    assert!(FixedGrid::new(1, 1, 1).is_ok());
}

#[test]
fn partial_time_carries_and_exact_interval_steps_once() {
    let mut grid = FixedGrid::new(5, 5, 10).unwrap();
    let right = HeldInput { right: true, ..HeldInput::default() };

    assert_eq!(grid.advance(0, &right), 0);
    assert_eq!((grid.x, grid.y), (0, 0));
    assert_eq!(grid.advance(6, &right), 0);
    assert_eq!(grid.advance(3, &right), 0);
    assert_eq!(grid.advance(1, &right), 1);
    assert_eq!((grid.x, grid.y), (1, 0));
    assert_eq!(grid.advance(10, &right), 1);
    assert_eq!((grid.x, grid.y), (2, 0));
}

#[test]
fn movement_cancels_per_axis_and_clamps_to_exclusive_bounds() {
    let mut grid = FixedGrid::new(3, 2, 1).unwrap();
    let down_right = HeldInput { right: true, down: true, ..HeldInput::default() };
    assert_eq!(grid.advance(20, &down_right), 20);
    assert_eq!((grid.x, grid.y), (2, 1));

    let opposing = HeldInput { left: true, right: true, up: true, down: true };
    assert_eq!(grid.advance(7, &opposing), 7);
    assert_eq!((grid.x, grid.y), (2, 1));

    let up_left = HeldInput { left: true, up: true, ..HeldInput::default() };
    assert_eq!(grid.advance(20, &up_left), 20);
    assert_eq!((grid.x, grid.y), (0, 0));
}

#[test]
fn axes_cancel_independently() {
    let mut grid = FixedGrid::new(5, 5, 1).unwrap();
    let input = HeldInput { left: true, right: true, down: true, up: false };
    assert_eq!(grid.advance(3, &input), 3);
    assert_eq!((grid.x, grid.y), (0, 3));
}

#[test]
fn mathematical_sum_survives_u64_overflow_boundary() {
    assert_bounded_exact_time_carry();

    let mut grid = FixedGrid::new(2, 1, 10).unwrap();
    let right = HeldInput { right: true, ..HeldInput::default() };

    assert_eq!(grid.advance(9, &right), 0);
    let expected = (((u64::MAX as u128) + 9) / 10) as usize;
    assert_eq!(grid.advance(u64::MAX, &right), expected);
    assert_eq!(grid.x, 1);

    assert_eq!(grid.advance(5, &right), 0);
    assert_eq!(grid.advance(1, &right), 1);
}

#[test]
fn maximum_representable_step_count_is_returned_without_a_huge_loop() {
    assert_bounded_exact_time_carry();

    let mut grid = FixedGrid::new(2, 1, 1).unwrap();
    let right = HeldInput { right: true, ..HeldInput::default() };
    assert_eq!(grid.advance(u64::MAX, &right), usize::MAX);
    assert_eq!((grid.x, grid.y), (1, 0));
    assert_eq!(grid.advance(0, &right), 0);
}

#[test]
fn borrowed_held_input_is_unchanged() {
    let mut grid = FixedGrid::new(3, 3, 1).unwrap();
    let input = HeldInput { left: false, right: true, up: true, down: false };
    let original = input;
    assert_eq!(grid.advance(2, &input), 2);
    assert_eq!(input, original);
}

