pub enum GridError {
    ZeroStep,
    ZeroWidth,
    ZeroHeight,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FixedGrid {
    pub x: usize,
    pub y: usize,
    width: usize,
    height: usize,
    step_ms: u64,
    accumulated_ms: u64,
}

impl FixedGrid {
    pub fn new(width: usize, height: usize, step_ms: u64) -> Result<Self, GridError> {
        if step_ms == 0 {
            return Err(GridError::ZeroStep);
        }
        if width == 0 {
            return Err(GridError::ZeroWidth);
        }
        if height == 0 {
            return Err(GridError::ZeroHeight);
        }
        Ok(Self { x: 0, y: 0, width, height, step_ms, accumulated_ms: 0 })
    }

    pub fn advance(&mut self, elapsed_ms: u64, input: &HeldInput) -> usize {
        let total = self.accumulated_ms as u128 + elapsed_ms as u128;
        let interval = self.step_ms as u128;
        let steps = (total / interval) as usize;
        self.accumulated_ms = (total % interval) as u64;

        if input.left != input.right {
            if input.left {
                self.x = self.x.saturating_sub(steps);
            } else {
                self.x = self.x.saturating_add(steps).min(self.width - 1);
            }
        }
        if input.up != input.down {
            if input.up {
                self.y = self.y.saturating_sub(steps);
            } else {
                self.y = self.y.saturating_add(steps).min(self.height - 1);
            }
        }

        steps
    }
}
